public async Task<Result<TokenPair>> RefreshAsync(string presentedToken)
{
    var stored = await _tokenStore.FindByTokenAsync(presentedToken);
    if (stored is null)
        return Result<TokenPair>.Fail("invalid_token");

    if (stored.IsRevoked)
    {
        // presented token already invalidated by a prior rotation -> reuse detected
        await _tokenStore.RevokeFamilyAsync(stored.FamilyId);
        return Result<TokenPair>.Fail("reuse_detected", forceReauth: true);
    }

    await _tokenStore.RevokeAsync(stored.Id); // single-use: invalidate immediately

    var newRefreshToken = _tokenFactory.CreateRefreshToken(stored.FamilyId, stored.UserId);
    await _tokenStore.SaveAsync(newRefreshToken);

    var accessToken = _tokenFactory.CreateAccessToken(stored.UserId);
    return Result<TokenPair>.Ok(new TokenPair(accessToken, newRefreshToken.Value));
}

