public class FileWriter : IDisposable
{
    private readonly FileStream _stream = File.OpenWrite("out.txt");
    private bool _disposed;

    public void Dispose()
    {
        if (_disposed) return;
        _stream.Dispose();       // deterministic cleanup
        _disposed = true;
        GC.SuppressFinalize(this); // finalizer no longer needed
    }

    ~FileWriter() => Dispose();  // safety net if Dispose was never called
}

