public class TokenBucket
{
    private double _tokens;
    private readonly double _capacity;
    private readonly double _refillPerSecond;
    private DateTime _lastRefill = DateTime.UtcNow;

    public bool TryConsume()
    {
        var now = DateTime.UtcNow;
        _tokens = Math.Min(_capacity, _tokens + (now - _lastRefill).TotalSeconds * _refillPerSecond);
        _lastRefill = now;
        if (_tokens < 1) return false;   // bucket empty -> request throttled
        _tokens -= 1;
        return true;                     // burst allowed up to capacity, then throttles to the refill rate
    }
}

