channel.BasicPublish("orders.exchange", routingKey: "orders.created", body: payload);
// the exchange decided where it goes; the queue is where it sits until a consumer calls BasicConsume

channel.BasicConsume(queue: "orders", autoAck: false, consumer: consumer); // manual ack required

consumer.Received += (model, ea) =>
{
    ProcessMessage(ea.Body);
    channel.BasicAck(ea.DeliveryTag, multiple: false); // only after processing genuinely succeeds
};

