[HttpPut("{id}")]
public async Task<IActionResult> Update(int id, UpdateDto dto)
{
    var entity = await _db.Widgets.FindAsync(id);
    var currentETag = Convert.ToBase64String(entity.RowVersion);

    if (Request.Headers.IfMatch != currentETag)
        return StatusCode(StatusCodes.Status412PreconditionFailed);

    entity.Name = dto.Name;
    await _db.SaveChangesAsync(); // RowVersion changes here
    Response.Headers.ETag = Convert.ToBase64String(entity.RowVersion);
    return NoContent();
}

